DROP TABLE IF EXISTS movies;
CREATE TABLE movies (NUM INT, CHECKED TEXT, COLORTAG INT, MEDIA TEXT, MEDIATYPE TEXT, SOURCE TEXT, DATEADDED DATE, BORROWER TEXT, DATEWATCHED DATE, USERRATING FLOAT, RATING FLOAT, ORIGINALTITLE TEXT, TRANSLATEDTITLE TEXT, FORMATTEDTITLE TEXT, DIRECTOR TEXT, PRODUCER TEXT, WRITER TEXT, COMPOSER TEXT, ACTORS TEXT, COUNTRY TEXT, YEAR INT, LENGTH INT, CATEGORY TEXT, CERTIFICATION TEXT, URL TEXT, DESCRIPTION TEXT, COMMENTS TEXT, FILEPATH TEXT, VIDEOFORMAT TEXT, VIDEOBITRATE INT, AUDIOFORMAT TEXT, AUDIOBITRATE INT, RESOLUTION TEXT, FRAMERATE TEXT, LANGUAGES TEXT, SUBTITLES TEXT, FILESIZE TEXT, DISKS INT, PICTURESTATUS TEXT, NBEXTRAS INT, PICTURENAME TEXT, PRIMARY KEY (NUM));
